const webhook = $('Webhook Chat').first().json.body;
const agentOut = $input.first().json;
const raw = agentOut.output ?? agentOut.text ?? '';

// Extrae ACTION:<tool> si el agente lo incluyó
const actionMatch = raw.match(/ACTION:([a-z_]+)/i);
const action_executed = actionMatch ? actionMatch[1].toLowerCase() : null;

// Limpia la línea ACTION del texto visible
const sinAction = raw.replace(/\n?ACTION:[a-z_]+/gi, '').trim();

// Limpia sintaxis markdown que React Native no puede renderizar como texto plano
function limpiarMarkdown(texto) {
  return texto
    .replace(/\*\*(.*?)\*\*/g, '$1')      // quita ** pero deja el texto
    .replace(/^#{1,6}\s*/gm, '')           // quita # de headers si el modelo los usa
    .replace(/^\s*-\s+/gm, '• ')           // convierte "- item" en "• item"
    .replace(/\n{3,}/g, '\n\n')            // evita más de 2 saltos de línea seguidos
    .trim();
}

const respuesta = limpiarMarkdown(sinAction);

const sugerenciasPorAccion = {
  buscar_cliente: ['Registrar un pago', 'Agregar crédito', 'Ver mora'],
  agregar_credito: ['Consultar saldo', 'Registrar pago'],
  agregar_pago: ['Ver historial', '¿Quién me debe más?'],
  agregar_cliente: ['Agregar crédito', 'Buscar cliente'],
};

return [{
  json: {
    respuesta,
    mensaje: respuesta,
    action_executed,
    sessionId: webhook.sessionId,
    sugerencias: action_executed
      ? (sugerenciasPorAccion[action_executed] ?? [])
      : ['¿Quién me debe más?', 'Créditos vencidos', '¿Cuánto me deben en total?'],
    success: true,
  },
}];

const base = 'https://fiadocheck-api.azurewebsites.net/api';
const webhook = $('Webhook Chat').first().json.body;
const token = webhook.authToken;

const clienteId = query.clienteId?.trim();
const montoTotal = Number(query.montoTotal);
const descripcion = query.descripcion?.trim() || '';
const fechaLimitePago = query.fechaLimitePago?.trim();

if (!token) return JSON.stringify({ error: 'authToken requerido' });
if (!clienteId || !montoTotal || !fechaLimitePago) {
  return JSON.stringify({ error: 'clienteId, montoTotal y fechaLimitePago son requeridos' });
}

try {
  const data = await this.helpers.httpRequest({
    method: 'POST',
    url: `${base}/creditos`,
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: { clienteId, montoTotal, descripcion, fechaLimitePago },
    json: true,
  });
  return JSON.stringify({ status: 201, data });
} catch (error) {
  const status = error.statusCode || 500;
  const msg = status === 403
    ? `El cliente con cédula ${clienteId} no está vinculado a tu cartera. Usa agregar_cliente primero.`
    : status === 404
    ? `No se encontró al cliente con cédula ${clienteId} en el sistema.`
    : error.message;
  return JSON.stringify({ status, error: msg });
}

