const monto = Number(query.monto);
const fechaAbono = query.fechaAbono?.trim() || new Date().toISOString().slice(0, 10);

if (!token) return JSON.stringify({ error: 'authToken requerido' });
if (!creditoId || !monto) return JSON.stringify({ error: 'creditoId y monto son requeridos' });
