try {
  const data = await this.helpers.httpRequest({
    method: 'POST',
    url: `${base}/creditos/${encodeURIComponent(creditoId)}/abonos`,
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: { monto, fechaAbono },
    json: true,
  });
  return JSON.stringify({ status: 200, data });
} catch (error) {
  const status = error.statusCode || 500;
  const msg = status === 404
    ? `No se encontró el crédito con ID ${creditoId}. Usa buscar_cliente para obtener el creditoId correcto.`
    : status === 403
    ? 'Este crédito no pertenece a un cliente de tu cartera.'
    : error.message;
  return JSON.stringify({ status, error: msg });
}

