const base = 'https://fiadocheck-api.azurewebsites.net/api';
const webhook = $('Webhook Chat').first().json.body;
const token = webhook.authToken;
const identificacion = query.identificacion?.trim();

if (!token) return JSON.stringify({ error: 'authToken requerido' });
if (!identificacion) return JSON.stringify({ error: 'La cédula (identificacion) del cliente es requerida' });

try {
  // 1. Verificar que el cliente existe en el sistema
  let clienteData;
  try {
    clienteData = await this.helpers.httpRequest({
      method: 'GET',
      url: `${base}/clientes/${encodeURIComponent(identificacion)}`,
      headers: { Authorization: `Bearer ${token}` },
      json: true,
    });
  } catch (lookupErr) {
    if (lookupErr.statusCode === 404) {
      return JSON.stringify({ error: `No existe ningún cliente con cédula ${identificacion} en el sistema. El cliente debe registrarse primero en la aplicación antes de poder vincularse a tu cartera.` });
    }
    throw lookupErr;
  }

  // 2. Asociar el cliente existente a la cartera del tendero
  const data = await this.helpers.httpRequest({
    method: 'POST',
    url: `${base}/clientes`,
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: {
      nombre: clienteData.nombre_completo,
      identificacion,
      telefono: clienteData.telefono,
      direccion: clienteData.direccion || ''
    },
    json: true,
  });
  return JSON.stringify({ status: 200, cliente_vinculado: clienteData.nombre_completo, id_cliente: clienteData.id_cliente, data });
} catch (error) {
  return JSON.stringify({ status: error.statusCode || 500, error: error.message });
}

