const base = 'https://fiadocheck-api.azurewebsites.net/api';
const webhook = $('Webhook Chat').first().json.body;
const token = webhook.authToken;
const idTendero = webhook.id_tendero ?? webhook.metadata?.id_tendero;

if (!token) {
  return JSON.stringify({ error: 'authToken requerido: el backend filtra por tendero vía JWT' });
}

const clienteId = query.clienteId?.trim();
const queryTexto = query.query?.trim();

const headers = { Authorization: `Bearer ${token}` };

async function fetchJson(url) {
  try {
    const data = await this.helpers.httpRequest({
      method: 'GET',
      url,
      headers,
      json: true,
    });
    return { status: 200, data };
  } catch (error) {
    return { status: error.statusCode || 500, data: { error: error.message } };
  }
}

if (clienteId) {
  const [detalle, historial, creditos] = await Promise.all([
    fetchJson.call(this, `${base}/clientes/${encodeURIComponent(clienteId)}`),
    fetchJson.call(this, `${base}/clientes/${encodeURIComponent(clienteId)}/historial`),
    fetchJson.call(this, `${base}/creditos/cliente/${encodeURIComponent(clienteId)}`),
  ]);
  return JSON.stringify({ id_tendero: idTendero, detalle: detalle.data, historial: historial.data, creditos_activos: creditos.data });
}

if (queryTexto) {
  const busqueda = await fetchJson.call(this, `${base}/clientes?q=${encodeURIComponent(queryTexto)}`);
  return JSON.stringify({ id_tendero: idTendero, resultados: busqueda.data });
}

return JSON.stringify({ error: 'Debes proporcionar clienteId o query' });

const base = 'https://fiadocheck-api.azurewebsites.net/api';
const webhook = $('Webhook Chat').first().json.body;
const token = webhook.authToken;

if (!token) return JSON.stringify({ error: 'authToken requerido' });

const headers = { Authorization: `Bearer ${token}` };
const deudaDe = (c) => Number(c.total_deuda ?? c.deuda_total ?? 0) || 0;

async function fetchJson(url) {
  try {
    const data = await this.helpers.httpRequest({ method: 'GET', url, headers, json: true });
    return { status: 200, data };
  } catch (error) {
    return { status: error.statusCode || 500, data: { error: error.message } };
  }
}

const [mora, alDia, sinDeuda] = await Promise.all([
  fetchJson.call(this, `${base}/clientes?estado=mora`),
  fetchJson.call(this, `${base}/clientes?estado=al_dia`),
  fetchJson.call(this, `${base}/clientes?estado=sin_deuda`),
]);

const listaMora = Array.isArray(mora.data) ? mora.data : (mora.data?.resultados ?? []);
const listaAlDia = Array.isArray(alDia.data) ? alDia.data : (alDia.data?.resultados ?? []);
const listaSinDeuda = Array.isArray(sinDeuda.data) ? sinDeuda.data : (sinDeuda.data?.resultados ?? []);
const totalPorCobrar = [...listaMora, ...listaAlDia].reduce((sum, c) => sum + deudaDe(c), 0);

return JSON.stringify({
  total_por_cobrar: totalPorCobrar,
  clientes_en_mora: listaMora.length,
  clientes_al_dia: listaAlDia.length,
  clientes_sin_deuda: listaSinDeuda.length,
});

const base = 'https://fiadocheck-api.azurewebsites.net/api';
const webhook = $('Webhook Chat').first().json.body;
const token = webhook.authToken;
const topN = Number(query.top_n) || 1;

if (!token) return JSON.stringify({ error: 'authToken requerido' });

const headers = { Authorization: `Bearer ${token}` };
const deudaDe = (c) => Number(c.total_deuda ?? c.deuda_total ?? 0) || 0;

async function fetchLista(url) {
  const data = await this.helpers.httpRequest({ method: 'GET', url, headers, json: true });
  return Array.isArray(data) ? data : (data?.resultados ?? []);
}

try {
  const [mora, alDia] = await Promise.all([
    fetchLista.call(this, `${base}/clientes?estado=mora`),
    fetchLista.call(this, `${base}/clientes?estado=al_dia`),
  ]);
  const lista = [...mora, ...alDia].filter((c) => deudaDe(c) > 0);
  const ordenado = [...lista].sort((a, b) => deudaDe(b) - deudaDe(a));
  return JSON.stringify({ top_deudores: ordenado.slice(0, topN) });
} catch (error) {
  return JSON.stringify({ status: error.statusCode || 500, error: error.message });
}

