const base = 'https://fiadocheck-api.azurewebsites.net/api';
const webhook = $('Webhook Chat').first().json.body;
const token = webhook.authToken;

if (!token) return JSON.stringify({ error: 'authToken requerido' });

try {
  const data = await this.helpers.httpRequest({
    method: 'GET',
    url: `${base}/clientes?estado=mora`,
    headers: { Authorization: `Bearer ${token}` },
    json: true,
  });

  const lista = Array.isArray(data) ? data : (data?.resultados ?? []);
  const hoy = new Date().toISOString().slice(0, 10);

  // Busca créditos activos de cada cliente en mora y filtra los vencidos
  const headers = { Authorization: `Bearer ${token}` };
  const detalles = await Promise.all(
    lista.map(async (c) => {
      const id = c.id_cliente ?? c.clienteId ?? c.identificacion;
      try {
        const creditos = await this.helpers.httpRequest({
          method: 'GET',
          url: `${base}/creditos/cliente/${encodeURIComponent(id)}`,
          headers,
          json: true,
        });
        const listaCreditos = Array.isArray(creditos) ? creditos : (creditos?.data ?? []);
        const vencidos = listaCreditos.filter(cr => {
          const fecha = cr.fechaLimitePago ?? cr.fecha_limite_pago;
          const saldo = cr.saldoPendiente ?? cr.saldo_pendiente ?? cr.montoTotal ?? cr.monto_total;
          return fecha && fecha < hoy && saldo > 0;
        });
        return vencidos.map(v => ({ cliente: c.nombre ?? c.nombre_completo, id_cliente: id, ...v }));
      } catch {
        return [];
      }
    })
  );

  return JSON.stringify({ creditos_vencidos: detalles.flat() });
} catch (error) {
  return JSON.stringify({ status: error.statusCode || 500, error: error.message });
}
